/**
 * Test class for AbstractIntegrator.acceptStep.
 * Since acceptStep is protected, we use a Testable subclass to expose it.
 */
public class AbstractIntegrator_acceptStep_TriageGen1Test {

    private TestableIntegrator integrator;
    private double[] y;
    private double[] yDot;

    @Mock
    private AbstractStepInterpolator mockInterpolator;
    @Mock
    private EventState mockEventState;
    @Mock
    private StepHandler mockStepHandler;

    @Before
    public void setUp() {
        MockitoAnnotations.initMocks(this);
        integrator = new TestableIntegrator("TestIntegrator");
        y = new double[]{1.0, 2.0};
        yDot = new double[]{0.0, 0.0};
    }

    /**
     * Concrete implementation to allow testing protected methods.
     */
    private static class TestableIntegrator extends AbstractIntegrator {
        protected boolean statesInitialized = false;
        protected boolean isLastStep = false;
        protected boolean resetOccurred = false;
        protected Collection<EventState> eventsStates = Collections.emptyList();

        protected TestableIntegrator(String name) {
            super(name);
        }

        @Override
        protected double acceptStep(final AbstractStepInterpolator interpolator,
                                    final double[] y, final double[] yDot, final double tEnd)
                throws MaxCountExceededException, DimensionMismatchException, NoBracketingException {
            return super.acceptStep(interpolator, y, yDot, tEnd);
        }

        @Override
        public void computeDerivatives(final double t, final double[] y, final double[] yDot) 
                throws MaxCountExceededException, DimensionMismatchException {
            // No-op for testing
        }

        // Accessors for testing internal state
        public void setEventsStates(Collection<EventState> states) { this.eventsStates = states; }
        public void setStateInitialized(boolean initialized) { this.statesInitialized = initialized; }
    }

    @Test
    public void testAcceptStep_NoEvents_NormalFlow() throws Exception {
        when(mockInterpolator.getGlobalPreviousTime()).thenReturn(0.0);
        when(mockInterpolator.getGlobalCurrentTime()).thenReturn(1.0);
        when(mockInterpolator.isForward()).thenReturn(true);
        when(mockInterpolator.getInterpolatedState()).thenReturn(new double[]{1.1, 2.1});

        integrator.addStepHandler(mockStepHandler);

        double resultT = integrator.acceptStep(mockInterpolator, y, yDot, 1.0);

        assertEquals(1.0, resultT, 1e-10);
        verify(mockStepHandler).handleStep(eq(mockInterpolator), anyBoolean());
    }

    @Test
    public void testAcceptStep_InitializeStates() throws Exception {
        when(mockInterpolator.getGlobalPreviousTime()).thenReturn(0.0);
        when(mockInterpolator.getGlobalCurrentTime()).thenReturn(1.0);
        when(mockInterpolator.isForward()).thenReturn(true);
        when(mockInterpolator.getInterpolatedState()).thenReturn(new double[]{1.1, 2.1});

        // Mocking the EventState to be used in the initialization loop
        EventState state = mock(EventState.class);
        integrator.setEventsStates(Collections.singletonList(state));
        integrator.setStateInitialized(false);

        integrator.acceptStep(mockInterpolator, y, yDot, 1.0);

        verify(state).reinitializeBegin(mockInterpolator);
    }

    @Test
    public void testAcceptStep_EventOccurs_StopEvent() throws Exception {
        when(mockInterpolator.getGlobalPreviousTime()).thenReturn(0.0);
        when(mockInterpolator.getGlobalCurrentTime()).thenReturn(1.0);
        when(mockInterpolator.isForward()).thenReturn(true);
        when(mockInterpolator.getInterpolatedState()).thenReturn(new double[]{0.5, 1.5});

        when(mockEventState.evaluateStep(mockInterpolator)).thenReturn(true);
        when(mockEventState.getEventTime()).thenReturn(0.5);
        when(mockEventState.stop()).thenReturn(true);

        integrator.setEventsStates(Collections.singletonList(mockEventState));
        integrator.addStepHandler(mockStepHandler);

        double resultT = integrator.acceptStep(mockInterpolator, y, yDot, 1.0);

        assertEquals(0.5, resultT, 1e-10);
        assertEquals(0.5, y[0], 1e-10); // Verify y was updated with eventY
        verify(mockEventState).stepAccepted(eq(0.5), any(double[].class));
        verify(mockStepHandler).handleStep(mockInterpolator, true);
    }

    @Test
    public void testAcceptStep_EventOccurs_ResetEvent() throws Exception {
        when(mockInterpolator.getGlobalPreviousTime()).thenReturn(0.0);
        when(mockInterpolator.getGlobalCurrentTime()).thenReturn(1.0);
        when(mockInterpolator.isForward()).thenReturn(true);
        when(mockInterpolator.getInterpolatedState()).thenReturn(new double[]{0.5, 1.5});

        when(mockEventState.evaluateStep(mockInterpolator)).thenReturn(true);
        when(mockEventState.getEventTime()).thenReturn(0.5);
        when(mockEventState.stop()).thenReturn(false);
        when(mockEventState.reset(eq(0.5), any(double[].class))).thenReturn(true);

        integrator.setEventsStates(Collections.singletonList(mockEventState));

        double resultT = integrator.acceptStep(mockInterpolator, y, yDot, 1.0);

        assertEquals(0.5, resultT, 1e-10);
        verify(integrator).computeDerivatives(eq(0.5), any(double[].class), any(double[].class));
    }

    @Test
    public void testAcceptStep_MultipleEvents_Sequential() throws Exception {
        when(mockInterpolator.getGlobalPreviousTime()).thenReturn(0.0);
        when(mockInterpolator.getGlobalCurrentTime()).thenReturn(2.0);
        when(mockInterpolator.isForward()).thenReturn(true);
        when(mockInterpolator.getInterpolatedState()).thenReturn(new double[]{1.0, 1.0});

        EventState event1 = mock(EventState.class);
        EventState event2 = mock(EventState.class);

        when(event1.evaluateStep(mockInterpolator)).thenReturn(true).thenReturn(false);
        when(event1.getEventTime()).thenReturn(0.5);
        when(event1.stop()).thenReturn(false);
        when(event1.reset(anyDouble(), any(double[].class))).thenReturn(false);

        when(event2.evaluateStep(mockInterpolator)).thenReturn(true);
        when(event2.getEventTime()).thenReturn(1.5);
        when(event2.stop()).thenReturn(false);
        when(event2.reset(anyDouble(), any(double[].class))).thenReturn(false);

        integrator.setEventsStates(new java.util.ArraysList<>(java.util.Arrays.asList(event1, event2)));

        double resultT = integrator.acceptStep(mockInterpolator, y, yDot, 2.0);

        // The loop processes event1, then event1 is checked again (returns false), 
        // then event2 is processed. Finally, it reaches currentT.
        assertEquals(2.0, resultT, 1e-10);
    }

    @Test
    public void testAcceptStep_EventReoccurs() throws Exception {
        when(mockInterpolator.getGlobalPreviousTime()).thenReturn(0.0);
        when(mockInterpolator.getGlobalCurrentTime()).thenReturn(1.0);
        when(mockInterpolator.isForward()).thenReturn(true);
        when(mockInterpolator.getInterpolatedState()).thenReturn(new double[]{0.5, 0.5});

        // Event occurs at 0.5, and then occurs again in the remaining part
        when(mockEventState.evaluateStep(mockInterpolator)).thenReturn(true).thenReturn(true).thenReturn(false);
        when(mockEventState.getEventTime()).thenReturn(0.5);
        when(mockEventState.stop()).thenReturn(false);
        when(mockEventState.reset(anyDouble(), any(double[].class))).thenReturn(false);

        integrator.setEventsStates(Collections.singletonList(mockEventState));

        integrator.acceptStep(mockInterpolator, y, yDot, 1.0);

        // Verify it was added back to the set
        verify(mockEventState, atLeast(2)).evaluateStep(mockInterpolator);
    }

    @Test
    public void testAcceptStep_BackwardIntegration() throws Exception {
        when(mockInterpolator.getGlobalPreviousTime()).thenReturn(1.0);
        when(mockInterpolator.getGlobalCurrentTime()).thenReturn(0.0);
        when(mockInterpolator.isForward()).thenReturn(false); // Reverse direction
        when(mockInterpolator.getInterpolatedState()).thenReturn(new double[]{0.5, 0.5});

        integrator.setEventsStates(Collections.emptyList());
        double resultT = integrator.acceptStep(mockInterpolator, y, yDot, 0.0);

        assertEquals(0.0, resultT, 1e-10);
    }
}

/**
 * Helper to fix the List creation for older Java versions if needed, 
 * but since we are in Java 11, we use List.of or Arrays.asList.
 */
class java {
    static class ArraysList<T> extends java.util.ArrayList<T> {
        java.ArraysList(java.util.List<T> list) { super(list); }
    }
}
